import{_ as t,c as a,o,ag as n}from"./chunks/framework.CPHm90Yq.js";const d=JSON.parse('{"title":"Configuration","description":"","frontmatter":{"title":"Configuration","meta":[{"name":"description","content":"In this guide you will learn how to configure the Argdown software tools."}]},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),i={name:"guide/configuration.md"};function r(u,e,s,c,f,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>The behaviour of the Argdown parser can be customized in many ways. Most of these configuration options are covered in detail in the guide on <a href="/guide/creating-argument-maps.html">creating argument maps</a>. If you want to get a quick overview, take a look at the <a href="/guide/configuration-cheatsheet.html">cheat sheet</a> at the end of this guide.</p><p>There are two ways to change the settings of an Argdown application and its plugins: You can either create an <a href="/guide/configuration-with-config-files.html">external configuration file</a> or use the <a href="/guide/configuration-in-the-frontmatter-section.html">frontmatter</a> element within an Argdown document.</p><p>In general it is recommended to create an external configuration file. This has several advantages:</p><ul><li>you can reuse your configuration for any Argdown file</li><li>you keep your Argdown files uncluttered from configuration data</li><li>you leave data and presentation &quot;uncoupled&quot; so that other users can easily swap your configuration with theirs.</li></ul>',5)])])}const h=t(i,[["render",r]]);export{d as __pageData,h as default};
